const adminSB = window.supabase.createClient(SGT_URL,SGT_KEY);
const ae = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const ad = v => v ? new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}) : '—';
const adt = v => v ? new Date(v).toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '—';
const addDays=(v,n)=>{if(!v)return null;const d=new Date(v+'T00:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const monthEnd=v=>{if(!v)return null;const d=new Date(v+'T00:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return d.toISOString().slice(0,10)};
function toast(m){const t=document.getElementById('toast');if(t){t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}}
async function currentUser(){const {data}=await adminSB.auth.getUser();return data.user||null}
async function getAdminMember(){const u=await currentUser();if(!u)return null;const role=u.user_metadata?.role; if(role==='admin'||role==='founder') return {user:u,role:'founder',permissions:['*']}; const {data}=await adminSB.from('sgt_admin_members').select('*').eq('user_id',u.id).eq('active',true).maybeSingle();return data?{user:u,role:data.role||'team_admin',permissions:Array.isArray(data.permissions)?data.permissions:[]}:null}
async function requireAdmin(){const a=await getAdminMember();if(!a){await adminSB.auth.signOut();location.href='admin-login.html';return null}return a}
async function getSetting(key){const {data,error}=await adminSB.from('sgt_settings').select('value').eq('key',key).maybeSingle();if(error)throw error;return data?.value||{}}
async function saveSetting(key,value,permission='settings.edit'){const {data,error}=await adminSB.rpc('sgt_admin_save_setting',{p_key:key,p_value:value,p_permission:permission});if(error)throw error;return data}
async function log(action,target_type='',target_id='',details={}){try{const u=await currentUser();if(!u)return;await adminSB.from('sgt_admin_audit').insert({admin_user:u.id,action,target_type,target_id,details})}catch(e){console.warn('Audit log failed',e)}}
function can(admin,permission){if(!admin)return false;if(admin.permissions?.includes('*'))return true;if(admin.permissions?.includes(permission))return true;const [section,action]=String(permission).split('.');return action==='view'&&admin.permissions?.includes(`${section}.edit`)}
function hasView(admin,view){if(admin?.role==='founder')return true;const map={dashboard:null,students:'students',registrations:'students',batches:'batches',domains:'domains',tasks:'tasks',assessment:'assessment',payments:'payments',documents:'documents',communication:'communication',services:'services',support:'support',enquiries:'enquiries',settings:'settings',team:'team',audit:'audit'};const section=map[view];if(!section)return view==='dashboard';return admin?.permissions?.includes(`${section}.view`)||admin?.permissions?.includes(`${section}.edit`)}
function viewName(v){return ({dashboard:'Dashboard',students:'Students',registrations:'New Registrations',batches:'Batches',domains:'Domains',tasks:'Tasks & Submission Forms',assessment:'Assessment',payments:'Payments',documents:'Documents',communication:'Communication',services:'Services',support:'Student Support',enquiries:'Client Enquiries',settings:'Settings',team:'Team & Access',audit:'Activity Log'})[v]||'Dashboard'}
let admin=null,students=[],domains=[],batches=[],tasks=[],questions=[],payments=[],enquiries=[],support=[],selectedIds=new Set(),noteSelection=new Set(),currentView='dashboard',paymentFiltered=[],paymentSelection=new Set(),noteStatusByUser=new Map();
function setView(v){if(!hasView(admin,v)){toast('You do not have access to this section.');return}currentView=v;document.querySelectorAll('.admin-view').forEach(x=>x.classList.remove('active'));document.getElementById('view-'+v)?.classList.add('active');document.querySelectorAll('#adminNav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const title=document.getElementById('viewTitle');if(title)title.textContent=viewName(v);document.getElementById('adminSidebar')?.classList.remove('open');if(v==='audit')renderAudit();if(v==='team')renderTeam();if(v==='payments')renderPayments()}
function statusClass(s){s=String(s||'').toLowerCase();return s.includes('verified')||s==='selected'||s==='complete'||s==='completed'?'success':s.includes('invalid')||s.includes('not selected')||s.includes('failed')?'danger':s.includes('pending')||s.includes('verification')||s.includes('review')?'warn':'blue'}
function batchStatus(start){if(!start)return'—';const t=new Date();t.setHours(0,0,0,0);const d=new Date(start+'T00:00:00'),e=new Date(monthEnd(start)+'T23:59:59');return d>t?'Upcoming':new Date()<=e?'Active':'Completed'}
function studentStatus(s){return s.selection_status==='Selected'?'Selected':s.selection_status==='Not Selected'?'Not Selected':s.status}
function renderMetrics(){const active=batches.filter(b=>batchStatus(b.start_date)==='Active').length;const selected=students.filter(s=>s.selection_status==='Selected').length;const notSelected=students.filter(s=>s.selection_status==='Not Selected').length;const pay=students.filter(s=>s.payment_status==='Verified').length;const pending=students.filter(s=>['Pending','Under Verification'].includes(s.payment_status)).length;const assess=students.filter(s=>s.assessment_status!=='Complete').length;const completed=students.filter(s=>s.status==='Completed').length;document.getElementById('dashboardMetrics').innerHTML=[['Total Students',students.length,'Registered accounts'],['Active Batches',active,'Currently running'],['Selected',selected,'Selection completed'],['Not Selected',notSelected,'Selection result'],['Payment Verified',pay,'Verified payments'],['Payment Pending',pending,'Awaiting verification'],['Assessment Pending',assess,'Not yet complete'],['Completed Programs',completed,'Program completed']].map(x=>`<div class="metric-card"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}
function renderDashboard(){renderMetrics();const recent=[...students].sort((a,b)=>new Date(b.registration_date)-new Date(a.registration_date)).slice(0,8);document.getElementById('newRegSummary').textContent=`${students.filter(s=>!s.batch_start).length} unassigned • ${students.length} total registrations`;document.getElementById('dashboardNewRows').innerHTML=recent.map(s=>`<tr><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.domain)}</td><td>${ad(s.registration_date)}</td><td>${ad(s.batch_start)}</td><td><span class="status ${statusClass(studentStatus(s))}">${ae(studentStatus(s))}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No registrations yet.</td></tr>';document.getElementById('dashboardBatchRows').innerHTML=batches.slice().sort((a,b)=>new Date(b.start_date)-new Date(a.start_date)).map(b=>`<tr><td>${ad(b.start_date)}</td><td>${ad(addDays(b.start_date,-2))}</td><td>${students.filter(s=>s.batch_start===b.start_date).length}</td><td><span class="status ${statusClass(batchStatus(b.start_date))}">${batchStatus(b.start_date)}</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No batches created yet.</td></tr>'}
function domainOptions(id,includeAll=true){const el=document.getElementById(id);if(!el)return;el.innerHTML=(includeAll?'<option value="">All domains</option>':'')+domains.map(d=>`<option value="${ae(d.name)}">${ae(d.name)}</option>`).join('')}
function filteredRegistrations(){const from=document.getElementById('regFrom').value,to=document.getElementById('regTo').value,dom=document.getElementById('regDomain').value,status=document.getElementById('regStatus').value;return students.filter(s=>{const day=(s.registration_date||'').slice(0,10);return(!from||day>=from)&&(!to||day<=to)&&(!dom||s.domain===dom)&&(!status||s.status===status)})}
function updateRegSelectButton(){const btn=document.getElementById('selectAllRegs');const list=filteredRegistrations();const all=list.length>0&&list.every(s=>selectedIds.has(s.id));if(btn){btn.textContent=all?'↩ Undo Selection':'Select All';btn.classList.toggle('danger',all)}document.getElementById('batchSelectedCount').textContent=`${selectedIds.size} selected`}
function renderRegistrations(){const list=filteredRegistrations();document.getElementById('regCount').textContent=`${list.length} students`;document.getElementById('registrationRows').innerHTML=list.map(s=>`<tr><td><input type="checkbox" class="reg-check" data-id="${s.id}" ${selectedIds.has(s.id)?'checked':''}></td><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.email)}<br>${ae(s.phone)}</td><td>${ae(s.country||'—')}</td><td>${ae(s.study_year||'—')}</td><td>${ae(s.domain)}</td><td>${ad(s.registration_date)}</td><td>${ad(s.batch_start)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No students match this filter.</td></tr>';document.querySelectorAll('.reg-check').forEach(c=>c.onchange=()=>{c.checked?selectedIds.add(c.dataset.id):selectedIds.delete(c.dataset.id);updateRegSelectButton()});updateRegSelectButton()}
function renderStudents(){const q=document.getElementById('studentSearch').value.trim().toLowerCase(),dom=document.getElementById('studentDomain').value;const list=students.filter(s=>(!q||[s.name,s.student_id,s.email,s.phone].join(' ').toLowerCase().includes(q))&&(!dom||s.domain===dom));document.getElementById('studentRows').innerHTML=list.map(s=>{const ns=noteStatusByUser.get(s.id);return `<tr><td><input class="student-note-check" type="checkbox" data-id="${ae(s.id)}" ${noteSelection.has(s.id)?'checked':''}></td><td><strong>${ae(s.student_id)}</strong><br>${ae(s.name)}</td><td>${ae(s.email)}<br>${ae(s.phone)}</td><td>${ae(s.domain)}</td><td>${ad(s.registration_date)}</td><td>${ad(s.batch_start)}</td><td><span class="status ${statusClass(s.payment_status)}">${ae(s.payment_status)}</span></td><td>${ae(s.assessment_status)}</td><td>${ae(s.selection_status)}</td><td>${ns?`<span class="status ${ns.read?'success':'warn'}">${ns.read?'Seen':'Sent'}</span><small class="note-seen-time">${adt(ns.read_at||ns.created_at)}</small>`:'<span class="help-note">—</span>'}</td><td><button class="portal-btn secondary student-open" data-id="${s.id}">Open</button></td></tr>`}).join('')||'<tr><td colspan="11" class="empty">No students found.</td></tr>';document.querySelectorAll('.student-note-check').forEach(c=>c.onchange=()=>{c.checked?noteSelection.add(c.dataset.id):noteSelection.delete(c.dataset.id);updateNoteSelectionUI()});document.querySelectorAll('.student-open').forEach(b=>b.onclick=()=>openStudent(b.dataset.id));updateNoteSelectionUI()}
function updateNoteSelectionUI(){const c=document.getElementById('studentNoteSelectedCount');if(c)c.textContent=`${noteSelection.size} selected`}
async function refreshNoteStatuses(){noteStatusByUser=new Map();const nr=await adminSB.from('sgt_student_notes').select('id,user_id,message,created_at').order('created_at',{ascending:false}).limit(1000);if(nr.error)return;const rr=await adminSB.from('sgt_student_notification_reads').select('notification_id,user_id,read_at');const reads=new Map((rr.data||[]).map(x=>[x.notification_id,x]));for(const n of (nr.data||[])){if(!noteStatusByUser.has(n.user_id)){const r=reads.get(n.id);noteStatusByUser.set(n.user_id,{read:!!r,read_at:r?.read_at||null,created_at:n.created_at})}}renderStudents()}
async function sendStudentNote(){if(!can(admin,'students.edit'))return toast('No permission.');const msg=document.getElementById('studentNoteMessage')?.value.trim(),category=document.getElementById('studentNoteCategory')?.value;if(!msg)return toast('Enter a note first.');if(!noteSelection.size)return toast('Select at least one student.');const rows=[...noteSelection].map(user_id=>({user_id,category,message:msg,created_by:admin.user.id}));const {error}=await adminSB.from('sgt_student_notes').insert(rows);if(error)return toast(error.message);await log('Sent student note','student',rows.map(x=>x.user_id).join(','),{category,count:rows.length});document.getElementById('studentNoteMessage').value='';noteSelection.clear();await refreshNoteStatuses();toast('Note sent to selected students.')}
function applyAdminNavIcons(){const icons={dashboard:'M3 12 12 3l9 9M5 10v10h14V10M9 20v-6h6v6',students:'M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2M9.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 8a3 3 0 1 1 0 6M21 21v-2a4 4 0 0 0-3-3',registrations:'M5 4h14v16H5zM8 8h8M8 12h8M8 16h5',batches:'M4 5h16v15H4zM8 3v4M16 3v4M4 9h16',domains:'M4 6h16M4 12h16M4 18h16M8 6v12M16 6v12',tasks:'M4 4h16v16H4zM8 9h8M8 13h8M8 17h5',assessment:'M5 3h14v18H5zM9 7h6M9 11h6M9 15h3',payments:'M4 6h16v12H4zM7 10h10M8 15h3',documents:'M6 3h9l4 4v14H6zM15 3v5h5M9 13h6M9 17h6',communication:'M4 5h16v12H8l-4 4zM8 9h8M8 13h5',services:'M12 3l2 4 4 1-3 3 .7 4.7L12 14l-3.3 1.7L9.4 11l-3-3 4-1z',support:'M4 5h16v12H8l-4 4zM8 9h8M8 13h5',enquiries:'M3 5h18v12H3zM7 9h10M7 13h6',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M18.4 5.6l-2.1 2.1M7.7 16.3l-2.1 2.1M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',team:'M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2M9.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M16 3.5a4 4 0 0 1 0 7.8',audit:'M4 5h16v14H4zM7 9h10M7 13h7M7 16h5'};document.querySelectorAll('#adminNav button[data-view]').forEach(b=>{const label=b.textContent.trim().replace(/^⌂\s*/,'');const path=icons[b.dataset.view]||'';b.innerHTML=`<svg class="admin-nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg><span>${label}</span>`})}

function openStudent(id){
  const s=students.find(x=>x.id===id);if(!s)return;
  const offerEligible=s.selection_status==='Selected';
  const certEligible=s.selection_status==='Selected'&&s.payment_status==='Verified'&&s.status==='Completed';
  const offerId=s.offer_letter_id||`SGT-OFFER-${String(s.student_id||'RECORD').replace(/[^0-9A-Z]/gi,'').slice(-10)}`;
  const certId=s.certificate_id||`SGT-CERT-${String(s.student_id||'RECORD').replace(/[^0-9A-Z]/gi,'').slice(-10)}`;
  document.getElementById('studentDrawerBody').innerHTML=`<div class="admin-card" style="margin-top:18px"><p><strong>${ae(s.name)}</strong><br>${ae(s.student_id)}<br>${ae(s.email)}</p><div class="portal-meta">${[['Phone',s.phone],['Country',s.country],['Study Year',s.study_year],['Gender',s.gender],['Domain',s.domain],['Registered',ad(s.registration_date)],['Batch',ad(s.batch_start)],['Payment',s.payment_status],['Assessment',s.assessment_status],['Selection',s.selection_status],['Selection Round',s.selection_round||1],['Review',s.review_status],['Refund',s.refund_status||'Not Started']].map(x=>`<div class="meta-box"><small>${x[0]}</small><strong>${ae(x[1]||'—')}</strong></div>`).join('')}</div></div><div class="admin-card"><h3>Document Eligibility</h3><div class="help-note">Offer Letter: <strong>${offerEligible?'Available':'Not issued'}</strong> • ${ae(offerId)}<br>Certificate: <strong>${certEligible?'Available':'Not issued'}</strong> • ${ae(certId)}</div></div><div class="admin-card"><h3>Program Access</h3><label class="check-row"><input id="editProjectOverride" type="checkbox" ${s.admin_project_override?'checked':''}> Manual Project / Task Access Override</label><small style="display:block;color:#64748b;margin-top:7px">This override only controls project/task visibility. It does not issue an Offer Letter or Certificate.</small></div><div class="admin-card"><h3>Update Student</h3><form id="studentEditForm" class="form-grid"><div class="field"><label>Domain</label><select id="editDomain">${domains.map(d=>`<option value="${ae(d.name)}" ${s.domain===d.name?'selected':''}>${ae(d.name)}</option>`).join('')}</select></div><div class="field"><label>Batch Start</label><input id="editBatch" type="date" value="${s.batch_start||''}"></div><div class="field"><label>Payment Status</label><select id="editPayment">${['Pending','Under Verification','Verified','Invalid','Refund Pending','Refunded'].map(x=>`<option ${s.payment_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Assessment Status</label><select id="editAssessment">${['Not Started','In Progress','Complete'].map(x=>`<option ${s.assessment_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Selection</label><select id="editSelection">${['Pending','Selected','Not Selected'].map(x=>`<option ${s.selection_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Program Status</label><select id="editStatus">${['Applicant','Active','Completed','Closed'].map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Selection Round</label><select id="editRound"><option value="1" ${Number(s.selection_round||1)===1?'selected':''}>Initial</option><option value="2" ${Number(s.selection_round||1)>=2?'selected':''}>Re-Assessment</option></select></div><div class="field"><label>Review</label><select id="editReview">${['Pending','Under Review','Complete','Reassessment Not Selected'].map(x=>`<option ${s.review_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Refund Status</label><select id="editRefund"><option value="">Not Started</option>${['Refund Process Pending','Refund Initiated','Refund Completed'].map(x=>`<option ${s.refund_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Refund Reference</label><input id="editRefundRef" value="${ae(s.refund_reference||'')}" placeholder="Optional reference"></div><div class="field full"><button class="portal-btn primary">Save Student Changes</button></div></form></div>`;
  document.getElementById('studentEditForm').onsubmit=async e=>{e.preventDefault();const patch={domain:document.getElementById('editDomain').value,batch_start:document.getElementById('editBatch').value||null,payment_status:document.getElementById('editPayment').value,assessment_status:document.getElementById('editAssessment').value,selection_status:document.getElementById('editSelection').value,status:document.getElementById('editStatus').value,selection_round:Number(document.getElementById('editRound').value),review_status:document.getElementById('editReview').value,refund_status:document.getElementById('editRefund').value||null,refund_reference:document.getElementById('editRefundRef').value.trim()||null,refund_completed_at:document.getElementById('editRefund').value==='Refund Completed'?new Date().toISOString():s.refund_completed_at||null,admin_project_override:document.getElementById('editProjectOverride').checked};await updateStudent(id,patch)};document.getElementById('studentDrawer').classList.add('open')
}
async function updateStudent(id,patch){if(!can(admin,'students.edit'))return toast('Your admin role does not have permission to edit students.');const before=students.find(x=>x.id===id);const {error}=await adminSB.from('sgt_profiles').update({...patch,updated_at:new Date().toISOString()}).eq('id',id);if(error)return toast(error.message);await log('Updated student','student',id,{before:{payment_status:before?.payment_status,selection_status:before?.selection_status,admin_project_override:before?.admin_project_override,refund_status:before?.refund_status},after:patch});if(patch.selection_status==='Selected'&&before?.selection_status!=='Selected')await triggerSelectionEmail(id);toast('Student updated and saved.');closeDrawer();await loadAll()}
async function triggerSelectionEmail(userId){try{const session=await adminSB.auth.getSession();const token=session.data.session?.access_token;if(!token)return;await fetch(`${SGT_URL}/functions/v1/sgt-send-selection-email`,{method:'POST',headers:{Authorization:`Bearer ${token}`,apikey:SGT_KEY,'Content-Type':'application/json'},body:JSON.stringify({user_id:userId})})}catch(e){console.warn('Selection email service unavailable.',e)}}
