function renderBatches(){document.getElementById('batchSelectedCount').textContent=`${selectedIds.size} selected`;document.getElementById('batchRows').innerHTML=batches.slice().sort((a,b)=>new Date(b.start_date)-new Date(a.start_date)).map(b=>`<tr><td>${ad(b.start_date)}</td><td>${ad(addDays(b.start_date,-2))}</td><td>${ad(monthEnd(b.start_date))}</td><td>${students.filter(s=>s.batch_start===b.start_date).length}</td><td>${b.whatsapp_group_url?`<a href="${ae(b.whatsapp_group_url)}" target="_blank" rel="noopener">Open Group</a>`:'—'}</td><td><span class="status ${statusClass(batchStatus(b.start_date))}">${batchStatus(b.start_date)}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No batches yet.</td></tr>'}
function renderDomains(){document.getElementById('domainRows').innerHTML=domains.map(d=>`<tr><td><strong>${ae(d.name)}</strong></td><td>${ae(d.description||'')}</td><td><span class="status ${d.enabled?'success':'danger'}">${d.enabled?'Enabled':'Disabled'}</span></td><td><button class="portal-btn secondary domain-edit" data-id="${d.id}">Edit</button> <button class="portal-btn ${d.enabled?'danger':'primary'} domain-toggle" data-id="${d.id}">${d.enabled?'Disable':'Enable'}</button></td></tr>`).join('');document.querySelectorAll('.domain-toggle').forEach(b=>b.onclick=async()=>{const d=domains.find(x=>x.id===b.dataset.id);if(!can(admin,'domains.edit'))return toast('No permission.');const {error}=await adminSB.from('sgt_domains').update({enabled:!d.enabled}).eq('id',d.id);if(error)return toast(error.message);await log(`${d.enabled?'Disabled':'Enabled'} domain`,'domain',d.id,{name:d.name,enabled:!d.enabled});await loadAll()});document.querySelectorAll('.domain-edit').forEach(b=>b.onclick=async()=>{const d=domains.find(x=>x.id===b.dataset.id);if(!can(admin,'domains.edit'))return toast('No permission.');const name=prompt('Domain name',d.name);if(name===null)return;const desc=prompt('Description',d.description||'');if(desc===null)return;const {error}=await adminSB.from('sgt_domains').update({name:name.trim(),description:desc.trim()}).eq('id',d.id);if(error)return toast(error.message);await log('Edited domain','domain',d.id,{name:name.trim(),description:desc.trim()});await loadAll()})}
async function renderTasks(){const tf=await getSetting('task_forms'),sc=await getSetting('program_schedule');document.getElementById('task1FormUrl').value=tf.task1||'';document.getElementById('task2FormUrl').value=tf.task2||'';document.getElementById('finalFormUrl').value=tf.final||'';const d=sc||{};[['t1open',d.task1?.open??0],['t1submit',d.task1?.submit??5],['t1deadline',d.task1?.deadline??6],['t1presStart',d.task1?.presentation_start??7],['t1presEnd',d.task1?.presentation_end??8],['t2open',d.task2?.open??9],['t2submit',d.task2?.submit??14],['t2deadline',d.task2?.deadline??15],['t2presStart',d.task2?.presentation_start??16],['t2presEnd',d.task2?.presentation_end??17],['fopen',d.final?.open??18],['fsubmit',d.final?.submit??24],['fdeadline',d.final?.deadline??26],['freview',d.final?.review_end??31]].forEach(x=>document.getElementById(x[0]).value=x[1]);document.getElementById('taskRows').innerHTML=tasks.map(t=>`<tr><td>${ae(t.title)}</td><td>${ae(t.domain||'All')}</td><td>${t.project_url?`<a href="${ae(t.project_url)}" target="_blank" rel="noopener">Open</a>`:'—'}</td><td><input type="checkbox" class="task-toggle" data-id="${t.id}" ${t.enabled?'checked':''}></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No task records.</td></tr>';document.querySelectorAll('.task-toggle').forEach(c=>c.onchange=async()=>{if(!can(admin,'tasks.edit'))return toast('No permission.');const {error}=await adminSB.from('sgt_tasks').update({enabled:c.checked}).eq('id',c.dataset.id);if(error)return toast(error.message);await log('Changed task visibility','task',c.dataset.id,{enabled:c.checked});await loadAll()})}
function renderQuestions(){document.getElementById('questionRows').innerHTML=questions.map(q=>`<tr><td>${ae(q.domain)}</td><td>${ae(q.question_set)}</td><td>${ae(q.question)}</td><td>${q.question_no}</td><td><input type="checkbox" class="question-toggle" data-id="${q.id}" ${q.enabled?'checked':''}></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No assessment questions published yet.</td></tr>';document.querySelectorAll('.question-toggle').forEach(c=>c.onchange=async()=>{if(!can(admin,'assessment.edit'))return toast('No permission.');const {error}=await adminSB.from('sgt_assessment_questions').update({enabled:c.checked}).eq('id',c.dataset.id);if(error)return toast(error.message);await log('Changed assessment question visibility','assessment_question',c.dataset.id,{enabled:c.checked});await loadAll()})}
function paymentList(){const q=(document.getElementById('paymentSearch')?.value||'').trim().toLowerCase(),from=document.getElementById('payFrom')?.value||'',to=document.getElementById('payTo')?.value||'',batchFrom=document.getElementById('payBatchFrom')?.value||'',batchTo=document.getElementById('payBatchTo')?.value||'',dom=document.getElementById('payDomain')?.value||'',status=document.getElementById('payStatus')?.value||'',method=document.getElementById('payMethodFilter')?.value||'';const hasFilter=Boolean(q||from||to||batchFrom||batchTo||dom||status||method);if(!hasFilter)return[];return payments.filter(x=>{const st=students.find(s=>s.student_id===x.student_id);const hay=[x.student_id,st?.name,st?.email,st?.phone,x.transaction_id].join(' ').toLowerCase();const sd=(x.submitted_at||'').slice(0,10),bd=(st?.batch_start||'').slice(0,10);return(!q||hay.includes(q))&&(!from||sd>=from)&&(!to||sd<=to)&&(!batchFrom||bd>=batchFrom)&&(!batchTo||bd<=batchTo)&&(!dom||st?.domain===dom)&&(!status||x.status===status)&&(!method||x.method===method)})}
