function renderPayments(){paymentFiltered=paymentList();document.getElementById('paymentCount').textContent=`${paymentFiltered.length} payment records`;document.getElementById('paymentRows').innerHTML=paymentFiltered.map(x=>{const st=students.find(s=>s.student_id===x.student_id);return `<tr><td><input type="checkbox" class="pay-check" data-id="${x.id}" ${paymentSelection.has(x.id)?'checked':''}></td><td><strong>${ae(x.student_id)}</strong><br>${ae(st?.name||'')}</td><td>${ae(st?.email||'')}</td><td>${ae(st?.domain||'—')}</td><td>${ae(x.method)}</td><td>${ae(x.transaction_id||'—')}</td><td>${ae(x.amount||'—')}</td><td>${adt(x.submitted_at)}</td><td>${x.receipt_path?`<button class="portal-btn secondary receipt-view" data-path="${ae(x.receipt_path)}">Receipt</button>`:'—'}</td><td><span class="status ${statusClass(x.status)}">${ae(x.status)}</span><br><select class="payment-status" data-id="${x.id}">${['Under Verification','Verified','Invalid','Refund Pending','Refunded'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><input class="payment-note" data-id="${x.id}" value="${ae(x.admin_note||'')}" placeholder="Add a note for student"></td></tr>`}).join('')||'<tr><td colspan="11" class="empty">Use the filters above to find payment records.</td></tr>';document.querySelectorAll('.pay-check').forEach(c=>c.onchange=()=>{c.checked?paymentSelection.add(c.dataset.id):paymentSelection.delete(c.dataset.id);updatePaymentSelectButton()});document.querySelectorAll('.receipt-view').forEach(b=>b.onclick=async()=>{const {data,error}=await adminSB.storage.from('payment-receipts').createSignedUrl(b.dataset.path,600);if(error)toast(error.message);else window.open(data.signedUrl,'_blank','noopener')});document.querySelectorAll('.payment-status').forEach(el=>el.onchange=async()=>updateSinglePayment(el.dataset.id,{status:el.value}));document.querySelectorAll('.payment-note').forEach(el=>el.onchange=async()=>updateSinglePayment(el.dataset.id,{admin_note:el.value}));updatePaymentSelectButton();renderPaymentEditor()}
async function updateSinglePayment(id,patch){if(!can(admin,'payments.edit'))return toast('No permission.');const x=payments.find(p=>p.id===id),before={status:x?.status,admin_note:x?.admin_note};const {error}=await adminSB.rpc('sgt_admin_update_payment',{p_payment_id:id,p_status:Object.prototype.hasOwnProperty.call(patch,'status')?patch.status:null,p_admin_note:Object.prototype.hasOwnProperty.call(patch,'admin_note')?patch.admin_note:null});if(error)return toast(error.message);await log('Updated payment','payment',id,{before,after:patch});toast('Payment updated and student dashboard synced.');await loadAll()}
async function bulkPaymentStatus(status){if(!paymentSelection.size)return toast('Select payment records first.');if(!can(admin,'payments.edit'))return toast('No permission.');const ids=[...paymentSelection];for(const id of ids){const r=await adminSB.rpc('sgt_admin_update_payment',{p_payment_id:id,p_status:status,p_admin_note:null});if(r.error)return toast(r.error.message)}await log('Bulk updated payment status','payment',ids.join(','),{status,count:ids.length});paymentSelection.clear();toast(`${ids.length} payment record(s) updated to ${status}.`);await loadAll()}
async function renderPaymentEditor(){const cfg=await getSetting('payment'),groups=[['india','India — UPI'],['pakistan','Pakistan — JazzCash / Easypaisa'],['binance','International — Binance'],['paypal','International — PayPal'],['wise','International — Wise']];document.getElementById('paymentSettingsEditor').innerHTML=`<form id="paymentSettingsForm" class="form-grid">${groups.map(g=>{const x=g[0]==='india'?cfg.india:g[0]==='pakistan'?cfg.pakistan:(cfg.international||{})[g[0]]||{};return `<div class="field"><label>${g[1]} — Fee</label><input id="fee_${g[0]}" value="${ae(x?.fee||'')}"/></div><div class="field"><label>${g[1]} — Currency</label><input id="cur_${g[0]}" value="${ae(x?.currency||'')}"/></div><div class="field full"><label>${g[1]} — Details</label><textarea id="det_${g[0]}" rows="3">${ae(x?.details||'')}</textarea></div><div class="field full"><label>${g[1]} — QR image URL</label><input id="qr_${g[0]}" value="${ae(x?.qr_url||'')}"/></div><div class="field full"><label><input type="checkbox" id="en_${g[0]}" ${x?.enabled!==false?'checked':''}/> Enabled</label></div>`}).join('')}<div class="field full"><button class="portal-btn primary">Save Payment Methods</button></div></form>`;document.getElementById('paymentSettingsForm').onsubmit=async e=>{e.preventDefault();if(!can(admin,'payments.edit'))return toast('No permission.');const next={india:{enabled:document.getElementById('en_india').checked,fee:document.getElementById('fee_india').value.trim(),currency:document.getElementById('cur_india').value.trim(),details:document.getElementById('det_india').value.trim(),qr_url:document.getElementById('qr_india').value.trim()},pakistan:{enabled:document.getElementById('en_pakistan').checked,fee:document.getElementById('fee_pakistan').value.trim(),currency:document.getElementById('cur_pakistan').value.trim(),details:document.getElementById('det_pakistan').value.trim(),qr_url:document.getElementById('qr_pakistan').value.trim()},international:{enabled:true,methods:['Binance','PayPal','Wise']}};['binance','paypal','wise'].forEach(k=>next.international[k]={enabled:document.getElementById('en_'+k).checked,fee:document.getElementById('fee_'+k).value.trim(),currency:document.getElementById('cur_'+k).value.trim(),details:document.getElementById('det_'+k).value.trim(),qr_url:document.getElementById('qr_'+k).value.trim()});next.international.enabled=next.international.binance.enabled||next.international.paypal.enabled||next.international.wise.enabled;await saveSetting('payment',next,'payments.edit');await log('Updated payment settings','settings','payment',next);toast('Payment settings saved.')}}
