async function renderTeam(){const box=document.getElementById('teamRows');if(!box)return;const q=(document.getElementById('teamSearch')?.value||'').trim().toLowerCase();const query=admin.role==='founder'?adminSB.from('sgt_admin_members').select('*').order('created_at',{ascending:false}):adminSB.from('sgt_admin_members').select('*').eq('user_id',admin.user.id).eq('active',true);const {data,error}=await query;if(error)return toast(error.message);const rows=(data||[]).filter(x=>!q||[x.email,x.role,(x.permissions||[]).join(' ')].join(' ').toLowerCase().includes(q));box.innerHTML=rows.map(x=>`<tr><td><strong>${ae(x.email)}</strong></td><td>${ae(x.role||'team_admin')}</td><td><span class="status ${x.active?'success':'danger'}">${x.active?'Active':'Removed'}</span></td><td>${ad(x.created_at)}</td><td>${ae((x.permissions||[]).join(', ')||'No permissions')}</td><td>${admin.role==='founder'?`<button class="portal-btn secondary team-edit" data-id="${x.id}">Edit Permissions</button> ${x.active?`<button class="portal-btn danger team-remove" data-id="${x.id}">Remove Access</button>`:`<button class="portal-btn primary team-restore" data-id="${x.id}">Restore</button>`}`:'<span class="pill">Your Access</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No team members found.</td></tr>';document.querySelectorAll('.team-edit').forEach(b=>b.onclick=()=>editTeamMember(b.dataset.id));document.querySelectorAll('.team-remove').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this team member access?'))return;const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:false});if(error)return toast(error.message);await log('Removed team admin access','admin_member',b.dataset.id);toast('Team member access removed.');renderTeam()});document.querySelectorAll('.team-restore').forEach(b=>b.onclick=async()=>{const {error}=await adminSB.rpc('sgt_set_admin_member_active',{p_member_id:b.dataset.id,p_active:true});if(error)return toast(error.message);await log('Restored team admin access','admin_member',b.dataset.id);toast('Team member access restored.');renderTeam()})}
async function editTeamMember(id){
  if(admin.role!=='founder')return toast('Founder access only.');
  const {data,error}=await adminSB.from('sgt_admin_members').select('*').eq('id',id).maybeSingle();
  if(error)return toast(error.message);if(!data)return;
  const groups={
    Students:['view','add','edit','delete'],
    Batches:['view','add','edit','delete'],
    Domains:['view','add','edit','delete'],
    Tasks:['view','add','edit','delete'],
    Assessment:['view','add','edit','delete'],
    Payments:['view','verify','edit'],
    Documents:['view','edit'],
    Communication:['view','edit'],
    Services:['view','edit'],
    Support:['view','edit'],
    Enquiries:['view','edit'],
    Settings:['view','edit']
  };
  const body=document.getElementById('permissionModalBody');if(!body)return;
  body.innerHTML=Object.entries(groups).map(([label,actions])=>{const section=label.toLowerCase();return `<div class="permission-group"><strong>${label}</strong>${actions.map(action=>{const value=`${section}.${action}`;return `<label><input type="checkbox" class="permission-choice" value="${ae(value)}" ${(data.permissions||[]).includes(value)?'checked':''}> ${action.charAt(0).toUpperCase()+action.slice(1)}</label>`}).join('')}</div>`}).join('');
  const modal=document.getElementById('permissionModal');modal.hidden=false;modal.classList.add('open');
  const close=()=>{modal.hidden=true;modal.classList.remove('open')};
  document.getElementById('permissionCancel').onclick=close;document.getElementById('permissionCancelTop').onclick=close;
  document.getElementById('permissionSave').onclick=async()=>{
    const perms=[...body.querySelectorAll('.permission-choice:checked')].map(x=>x.value);
    const b=document.getElementById('permissionSave');b.disabled=true;b.textContent='Saving…';
    const {error:e}=await adminSB.rpc('sgt_update_admin_member_permissions',{p_member_id:id,p_permissions:perms});
    if(e){toast(e.message);b.disabled=false;b.textContent='Save Permissions';return}
    await log('Updated team admin permissions','admin_member',id,{email:data.email,permissions:perms});toast('Permissions updated.');b.disabled=false;b.textContent='Save Permissions';close();renderTeam();
  };
}
async function renderAudit(){if(admin.role!=='founder'){document.getElementById('auditRows').innerHTML='<tr><td colspan="4" class="empty">Founder access only.</td></tr>';return}const q=(document.getElementById('auditSearch')?.value||'').trim().toLowerCase();const {data,error}=await adminSB.from('sgt_admin_audit').select('*').order('created_at',{ascending:false}).limit(1000);if(error)return toast(error.message);const mr=await adminSB.from('sgt_admin_members').select('user_id,email,role');const members=mr.data||[];const names=new Map(members.map(m=>[m.user_id,m.email]));const teamBox=document.getElementById('auditTeamList');if(teamBox)teamBox.innerHTML='<span class="pill">Filter by team:</span>'+members.map(m=>`<button type="button" class="portal-btn secondary audit-team-chip" data-email="${ae(m.email)}">${ae(m.email)}</button>`).join('');teamBox?.querySelectorAll('.audit-team-chip').forEach(b=>b.onclick=()=>{const inp=document.getElementById('auditSearch');if(inp){inp.value=b.dataset.email;renderAudit()}});const rows=(data||[]).filter(x=>!q||[x.action,x.target_type,x.target_id,JSON.stringify(x.details||{}),names.get(x.admin_user)||'Founder'].join(' ').toLowerCase().includes(q));document.getElementById('auditRows').innerHTML=rows.map(x=>`<tr><td>${adt(x.created_at)}</td><td><strong>${ae(names.get(x.admin_user)||'Founder')}</strong><br>${ae(x.action)}</td><td>${ae(x.target_type||'')} ${ae(x.target_id||'')}</td><td><pre style="white-space:pre-wrap;margin:0;font:inherit;color:#475569">${ae(JSON.stringify(x.details||{},null,2))}</pre></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No activity matches your search.</td></tr>'}
async function loadAll(){try{const results=await Promise.all([adminSB.from('sgt_profiles').select('*').order('registration_date',{ascending:false}),adminSB.from('sgt_domains').select('*').order('name'),adminSB.from('sgt_batches').select('*').order('start_date',{ascending:false}),adminSB.from('sgt_tasks').select('*').order('title'),adminSB.from('sgt_assessment_questions').select('*').order('domain').order('question_set').order('question_no'),adminSB.from('sgt_payments').select('*').order('submitted_at',{ascending:false}),adminSB.from('sgt_client_enquiries').select('*').order('created_at',{ascending:false}),adminSB.from('sgt_support_queries').select('*').order('created_at',{ascending:false})]);for(const r of results)if(r.error)throw r.error;students=results[0].data||[];domains=results[1].data||[];batches=results[2].data||[];tasks=results[3].data||[];questions=results[4].data||[];payments=results[5].data||[];enquiries=results[6].data||[];support=results[7].data||[];await refreshNoteStatuses();renderDashboard();domainOptions('regDomain');domainOptions('studentDomain');domainOptions('payDomain');renderRegistrations();renderStudents();renderBatches();renderDomains();renderQuestions();renderDocuments();renderSupport();renderEnquiries();await renderTasks();await renderCommunication();await renderServices();await renderSettings();renderPayments();if(currentView==='audit')await renderAudit();if(currentView==='team')await renderTeam()}catch(e){const er=document.querySelector('.admin-error');if(er)er.textContent=e.message;console.error(e)}}
async function setupAdmin2FA(){if(admin.role!=='founder')return toast('Founder access only.');const {data,error}=await adminSB.auth.mfa.enroll({factorType:'totp',friendlyName:'SoftGrowTech Founder Admin'});if(error)return toast(error.message);const modal=document.getElementById('twoFaSetup');modal.hidden=false;document.getElementById('twoFaQr').src=data.totp.qr_code;document.getElementById('twoFaSecret').textContent=data.totp.secret;document.getElementById('twoFaVerify').onclick=async()=>{const code=document.getElementById('twoFaCode').value.trim();const ch=await adminSB.auth.mfa.challenge({factorId:data.id});if(ch.error)return toast(ch.error.message);const vr=await adminSB.auth.mfa.verify({factorId:data.id,challengeId:ch.data.id,code});if(vr.error)return toast(vr.error.message);await saveSetting('admin_2fa',{enabled:true});await log('Enabled founder 2FA','security','admin_2fa');modal.hidden=true;toast('Two-factor authentication enabled.');renderSettings()}}
async function initAdmin(){admin=await requireAdmin();if(!admin)return;document.getElementById('adminEmail').textContent=`${admin.user.email} • ${admin.role==='founder'?'Founder':'Team Admin'}`;applyAdminNavIcons();document.getElementById('adminLogout').onclick=async()=>{await log('Logged out','admin',admin.user.id);await adminSB.auth.signOut();location.href='admin-login.html'};if(admin.role!=='founder'){document.querySelector('#adminNav button[data-view=\"audit\"]')?.remove();const add=document.getElementById('addTeamForm');if(add)add.closest('.admin-card').style.display='none';const audit=document.getElementById('view-audit');if(audit)audit.remove();}document.querySelectorAll('#adminNav button[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>setView(b.dataset.goto));document.getElementById('adminMenuToggle').onclick=()=>document.getElementById('adminSidebar').classList.toggle('open');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('studentDrawer').onclick=e=>{if(e.target.id==='studentDrawer')closeDrawer()};document.getElementById('filterRegs').onclick=renderRegistrations;document.getElementById('selectAllRegs').onclick=()=>{const list=filteredRegistrations(),all=list.length>0&&list.every(s=>selectedIds.has(s.id));list.forEach(s=>all?selectedIds.delete(s.id):selectedIds.add(s.id));renderRegistrations();document.getElementById('selectAllRegs').textContent=all?'Select All':'Undo Selection'};document.getElementById('assignSelected').onclick=()=>setView('batches');document.getElementById('filterStudents').onclick=renderStudents;document.getElementById('selectAllStudentNotes')?.addEventListener('click',()=>{const q=document.getElementById('studentSearch').value.trim().toLowerCase(),dom=document.getElementById('studentDomain').value;const list=students.filter(s=>(!q||[s.name,s.student_id,s.email,s.phone].join(' ').toLowerCase().includes(q))&&(!dom||s.domain===dom));const all=list.length>0&&list.every(s=>noteSelection.has(s.id));list.forEach(s=>all?noteSelection.delete(s.id):noteSelection.add(s.id));renderStudents()});document.getElementById('sendStudentNote')?.addEventListener('click',sendStudentNote);document.getElementById('addDomainForm').onsubmit=async e=>{e.preventDefault();if(!can(admin,'domains.edit'))return toast('No permission.');const domainName=document.getElementById('newDomain').value.trim(),domainDescription=document.getElementById('newDomainDescription').value.trim();const {error}=await adminSB.from('sgt_domains').insert({name:domainName,description:domainDescription,enabled:true});if(error)return toast(error.message);e.target.reset();await log('Added domain','domain','',{name:domainName,description:domainDescription});await loadAll()};document.getElementById('assignBatchBtn').onclick=async()=>{if(!can(admin,'batches.edit'))return toast('No permission.');const date=document.getElementById('batchDate').value;if(!date)return toast('Choose a batch start date.');if(!selectedIds.size)return toast('Select students first.');const group=document.getElementById('batchGroup').value.trim();let b=batches.find(x=>x.start_date===date);if(!b){const ins=await adminSB.from('sgt_batches').insert({start_date:date,whatsapp_group_url:group}).select().single();if(ins.error)return toast(ins.error.message);b=ins.data}else if(group){const up=await adminSB.from('sgt_batches').update({whatsapp_group_url:group}).eq('id',b.id);if(up.error)return toast(up.error.message)}const {error}=await adminSB.from('sgt_profiles').update({batch_start:date,whatsapp_group_url:group||b.whatsapp_group_url||null,updated_at:new Date().toISOString()}).in('id',[...selectedIds]);if(error)return toast(error.message);await log('Assigned students to batch','batch',b.id,{start_date:date,count:selectedIds.size});selectedIds.clear();toast('Students assigned to batch.');await loadAll();setView('batches')};document.getElementById('taskFormsForm').onsubmit=async e=>{e.preventDefault();if(!can(admin,'tasks.edit'))return toast('No permission.');await saveSetting('task_forms',{task1:document.getElementById('task1FormUrl').value.trim(),task2:document.getElementById('task2FormUrl').value.trim(),final:document.getElementById('finalFormUrl').value.trim()},'tasks.edit');await log('Updated task submission form links','settings','task_forms');toast('Submission form links saved.')};document.getElementById('scheduleForm').onsubmit=async e=>{e.preventDefault();if(!can(admin,'tasks.edit'))return toast('No permission.');const n=id=>Number(document.getElementById(id).value||0);const v={task1:{open:n('t1open'),submit:n('t1submit'),deadline:n('t1deadline'),presentation_start:n('t1presStart'),presentation_end:n('t1presEnd')},task2:{open:n('t2open'),submit:n('t2submit'),deadline:n('t2deadline'),presentation_start:n('t2presStart'),presentation_end:n('t2presEnd')},final:{open:n('fopen'),submit:n('fsubmit'),deadline:n('fdeadline'),review_end:n('freview')}};await saveSetting('program_schedule',v,'tasks.edit');await log('Updated program schedule','settings','program_schedule',v);toast('Program schedule saved.')};document.getElementById('registrationGroupForm').onsubmit=async e=>{e.preventDefault();await saveSetting('registration_group',{url:document.getElementById('registrationGroupUrl').value.trim()});await log('Updated registration WhatsApp group','settings','registration_group');toast('Registration group link saved.')};document.getElementById('idSettingsForm').onsubmit=async e=>{e.preventDefault();const prefix=document.getElementById('idPrefix').value.trim(),year=document.getElementById('idYear').value.trim(),last=Number(document.getElementById('idLast').value);if(!prefix||!year||Number.isNaN(last))return toast('Enter valid ID settings.');if(!confirm(`Set last used number to ${last}? Existing Student IDs will not change.`))return;await saveSetting('student_id',{prefix,year_code:year,last_used:last});await log('Updated Student ID sequence','settings','student_id',{prefix,year_code:year,last_used:last});toast('Student ID settings saved.');renderSettings()};document.getElementById('filterPayments').onclick=renderPayments;document.getElementById('selectAllPayments').onclick=()=>{const list=paymentFiltered,all=list.length>0&&list.every(x=>paymentSelection.has(x.id));list.forEach(x=>all?paymentSelection.delete(x.id):paymentSelection.add(x.id));renderPayments();document.getElementById('selectAllPayments').textContent=all?'Select All':'Undo Selection'};document.querySelectorAll('[data-pay-bulk]').forEach(b=>b.onclick=()=>bulkPaymentStatus(b.dataset.payBulk));document.getElementById('paymentBulkStatus').onchange=e=>{if(e.target.value)bulkPaymentStatus(e.target.value);e.target.value=''};document.getElementById('addTeamForm').onsubmit=async e=>{e.preventDefault();if(admin.role!=='founder')return toast('Founder access only.');const email=document.getElementById('teamEmail').value.trim().toLowerCase(),role=document.getElementById('teamRole').value,perms=[...document.querySelectorAll('.team-permission:checked')].map(x=>x.value);if(!email)return toast('Enter the team member email.');const {data,error}=await adminSB.rpc('sgt_add_admin_member',{p_email:email,p_role:role,p_permissions:perms});if(error)return toast(error.message);e.target.reset();toast('Team member access added. They can sign in with their own Supabase Auth account.');await log('Added team admin','admin_member',data?.id||'',{email,role,permissions:perms});renderTeam()};document.getElementById('teamSearch')?.addEventListener('input',renderTeam);document.getElementById('auditSearch')?.addEventListener('input',renderAudit);document.getElementById('setup2faBtn').onclick=setupAdmin2FA;await log('Logged in','admin',admin.user.id,{role:admin.role});await loadAll()}
document.addEventListener('DOMContentLoaded',async()=>{const login=document.getElementById('adminLogin');if(login)login.onsubmit=async e=>{e.preventDefault();const b=login.querySelector('button');b.disabled=true;b.textContent='Signing in…';const {error}=await adminSB.auth.signInWithPassword({email:document.getElementById('adminEmailInput').value.trim(),password:document.getElementById('adminPassword').value});if(error){toast(error.message);b.disabled=false;b.textContent='Sign In →';return}const a=await getAdminMember();if(!a){await adminSB.auth.signOut();toast('This account is not authorized for the Management Console.');b.disabled=false;b.textContent='Sign In →';return}const aal=await adminSB.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.data?.currentLevel==='aal1'&&aal.data?.nextLevel==='aal2'){const factors=await adminSB.auth.mfa.listFactors();const factor=factors.data?.totp?.find(x=>x.status==='verified');if(factor){const ch=await adminSB.auth.mfa.challenge({factorId:factor.id});if(ch.error){toast(ch.error.message);return}const code=prompt('Enter your 2FA authenticator code');if(!code){await adminSB.auth.signOut();return}const vr=await adminSB.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code});if(vr.error){await adminSB.auth.signOut();toast('Invalid 2FA code.');return}}}location.href='management-console-x7.html'};if(document.getElementById('adminRoot'))initAdmin()});
